work(DITCH:grow(2.5), {hand="detail", pile=bankp, angle=-0.3, coverage=3, fill=true, length={6,16}, seed=352})
work(DITCH:shrink(0.6), {hand="detail", pile=ditchw, angle=-0.33, coverage=3.5, fill=true, length={6,20}, seed=353})
